const CHILE=[
{n:'Manuel Blanco Encalada',o:'1.er presidente',y:'1826',c:'XIX',p:'Independiente',r:'No',s:'Santiago',a:'Española',w:'Guerra de Independencia; campaña de Chiloé',d:'No',x:['Fue el primer ciudadano en usar formalmente el título de Presidente de la República de Chile, aunque renunció tras dos meses ante el conflicto federal.','Como marino dirigió la escuadra chilena y más tarde ejerció misiones diplomáticas decisivas para el Estado republicano.']},
{n:'Agustín de Eyzaguirre',o:'Presidente interino',y:'1826–1827',c:'XIX',p:'Conservador',r:'No',s:'Santiago',a:'Española',w:'Crisis política de organización republicana',d:'No',x:['Encabezó el gobierno interino durante la experiencia federal y trató de sostener la administración en un periodo de gran fragmentación política.','Su mandato terminó con el motín de Campino, episodio que precipitó el retorno de Ramón Freire.']},
{n:'Ramón Freire',o:'Presidente',y:'1827',c:'XIX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Guerra de Independencia; incorporación de Chiloé',d:'No',x:['Como Director Supremo abolió definitivamente la esclavitud en Chile y condujo la campaña que incorporó Chiloé en 1826.','En la presidencia impulsó el orden liberal, pero renunció ante la inestabilidad institucional.']},
{n:'Francisco Antonio Pinto',o:'Presidente',y:'1827–1829',c:'XIX',p:'Liberal',r:'No',s:'Santiago',a:'Española y portuguesa',w:'Inicio de la Guerra Civil de 1829',d:'No',x:['Promulgó la Constitución liberal de 1828, que amplió derechos y organizó la república bajo principios representativos.','La disputa por su sucesión desembocó en la Guerra Civil de 1829 y en el triunfo conservador.']},
{n:'Francisco Ramón Vicuña',o:'Presidente interino',y:'1829',c:'XIX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Guerra Civil de 1829',d:'No',x:['Asumió interinamente durante la crisis constitucional que siguió a las elecciones de 1829.','Fue capturado por fuerzas conservadoras y dejó el poder cuando la guerra civil desarticuló al gobierno liberal.']},
{n:'José Tomás Ovalle',o:'Presidente provisional',y:'1830–1831',c:'XIX',p:'Conservador',r:'No',s:'Santiago',a:'Española',w:'Fin de la Guerra Civil de 1829–1830',d:'Sí',x:['Condujo la transición tras la victoria conservadora de Lircay y restableció el funcionamiento de la administración pública.','Su gobierno preparó el ciclo institucional de 1831, pero murió en ejercicio antes de completarlo.']},
{n:'José Joaquín Prieto',o:'Presidente',y:'1831–1841',c:'XIX',p:'Conservador',r:'Sí',s:'Concepción',a:'Española',w:'Guerra contra la Confederación Perú-Boliviana',d:'No',x:['Promulgó la Constitución de 1833, base del orden político chileno durante casi un siglo.','Su gobierno consolidó las finanzas públicas y venció a la Confederación Perú-Boliviana en Yungay.']},
{n:'Manuel Bulnes',o:'Presidente',y:'1841–1851',c:'XIX',p:'Conservador',r:'Sí',s:'Concepción',a:'Española',w:'Revolución de 1851 al final del mandato',d:'No',x:['Fundó la Universidad de Chile en 1842 y fortaleció la educación, la cultura y la administración estatal.','Impulsó la ocupación del estrecho de Magallanes y una política de expansión territorial hacia el sur.']},
{n:'Manuel Montt',o:'Presidente',y:'1851–1861',c:'XIX',p:'Nacional',r:'Sí',s:'Petorca',a:'Española',w:'Revoluciones de 1851 y 1859',d:'No',x:['Expandió ferrocarriles, caminos, escuelas y servicios públicos durante una década de modernización material.','Promulgó el Código Civil de 1855 y enfrentó dos guerras civiles que erosionaron el predominio conservador.']},
{n:'José Joaquín Pérez',o:'Presidente',y:'1861–1871',c:'XIX',p:'Nacional',r:'Sí',s:'Santiago',a:'Española',w:'Guerra contra España; ocupación de la Araucanía',d:'No',x:['Inauguró la República Liberal mediante una política de conciliación y reformas que limitaron el autoritarismo presidencial.','Durante su mandato Chile combatió a España y profundizó la ocupación estatal de la Araucanía.']},
{n:'Federico Errázuriz Zañartu',o:'Presidente',y:'1871–1876',c:'XIX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Ocupación de la Araucanía',d:'No',x:['Impulsó reformas constitucionales que redujeron el poder presidencial y ampliaron las libertades públicas.','Firmó el tratado limítrofe de 1874 con Bolivia y promovió obras ferroviarias y urbanas.']},
{n:'Aníbal Pinto',o:'Presidente',y:'1876–1881',c:'XIX',p:'Liberal',r:'No',s:'Valparaíso',a:'Española y portuguesa',w:'Guerra del Pacífico',d:'No',x:['Enfrentó una severa crisis económica al asumir y reorganizó el gasto y la administración fiscal.','Condujo la primera fase de la Guerra del Pacífico, incluida la campaña marítima y la ocupación de Lima.']},
{n:'Domingo Santa María',o:'Presidente',y:'1881–1886',c:'XIX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Guerra del Pacífico; ocupación de la Araucanía',d:'No',x:['Concluyó la Guerra del Pacífico mediante los tratados de Ancón con Perú y de tregua con Bolivia.','Promulgó las leyes laicas de cementerios, matrimonio y registro civil, reduciendo el control eclesiástico.']},
{n:'José Manuel Balmaceda',o:'Presidente',y:'1886–1891',c:'XIX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Guerra Civil de 1891',d:'No',x:['Financió una amplia red de escuelas, ferrocarriles y obras públicas con los ingresos del salitre.','Su choque con el Congreso derivó en la Guerra Civil de 1891; derrotado, se suicidó el día en que terminaba su mandato.']},
{n:'Jorge Montt',o:'Presidente',y:'1891–1896',c:'XIX',p:'Independiente',r:'No',s:'Casablanca',a:'Española',w:'Posguerra civil y reorganización institucional',d:'No',x:['Encabezó la transición posterior a la guerra civil e inauguró el régimen parlamentario chileno.','Ordenó las finanzas, impulsó la conversión monetaria y profesionalizó las Fuerzas Armadas.']},
{n:'Federico Errázuriz Echaurren',o:'Presidente',y:'1896–1901',c:'XIX / XX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Tensiones limítrofes con Argentina',d:'Sí',x:['Gestionó la grave disputa fronteriza con Argentina y sostuvo la vía arbitral que evitó una guerra.','Su gobierno promovió obras urbanas y sanitarias, pero quedó debilitado por la rotación ministerial; murió en ejercicio.']},
{n:'Germán Riesco',o:'Presidente',y:'1901–1906',c:'XX',p:'Liberal',r:'No',s:'Rancagua',a:'Española',w:'Conflictos sociales; huelga de Valparaíso',d:'No',x:['Firmó los Pactos de Mayo de 1902 con Argentina y el Tratado de Paz y Amistad de 1904 con Bolivia.','Amplió la infraestructura judicial y educativa mientras crecían la cuestión social y las huelgas obreras.']},
{n:'Pedro Montt',o:'Presidente',y:'1906–1910',c:'XX',p:'Nacional',r:'No',s:'Santiago',a:'Española',w:'Matanza de la Escuela Santa María de Iquique',d:'Sí',x:['Aceleró la construcción ferroviaria, incluida la línea longitudinal y el ferrocarril transandino.','Su gobierno respondió con violencia a la movilización obrera de Iquique en 1907; murió en ejercicio en 1910.']},
{n:'Ramón Barros Luco',o:'Presidente',y:'1910–1915',c:'XX',p:'Liberal',r:'No',s:'Santiago',a:'Española',w:'Primera Guerra Mundial — neutralidad',d:'No',x:['Mantuvo la neutralidad chilena durante el inicio de la Primera Guerra Mundial.','Impulsó obras portuarias, ferroviarias y sanitarias, y dejó como legado el hospital que lleva su nombre.']},
{n:'Juan Luis Sanfuentes',o:'Presidente',y:'1915–1920',c:'XX',p:'Liberal Democrático',r:'No',s:'Santiago',a:'Española',w:'Primera Guerra Mundial — neutralidad; conflicto social',d:'No',x:['Conservó la neutralidad durante la Primera Guerra Mundial y promulgó tempranas leyes sociales.','Su mandato estuvo marcado por inflación, protestas obreras y una intensa inestabilidad ministerial.']},
{n:'Arturo Alessandri',o:'Presidente',y:'1920–1925 · 1932–1938',c:'XX',p:'Liberal',r:'No consecutiva',s:'Longaví',a:'Italiana',w:'Golpes militares de 1924 y 1925; crisis política de 1932',d:'No',x:['Impulsó legislación laboral, previsional y social que respondió parcialmente a la cuestión social.','Promulgó la Constitución de 1925, que restableció el presidencialismo y separó formalmente la Iglesia del Estado.']},
{n:'Emiliano Figueroa Larraín',o:'Presidente',y:'1925–1927',c:'XX',p:'Liberal Democrático',r:'No',s:'Santiago',a:'Española',w:'Presión militar y crisis institucional',d:'No',x:['Asumió tras la Constitución de 1925 con la tarea de normalizar el régimen civil.','Renunció ante la creciente concentración de poder de Carlos Ibáñez del Campo y la crisis provocada por la destitución de su hermano.']},
{n:'Carlos Ibáñez del Campo',o:'Presidente',y:'1927–1931 · 1952–1958',c:'XX',p:'Independiente',r:'No consecutiva',s:'Linares',a:'Española',w:'Represión política; crisis de 1931',d:'No',x:['En su primer gobierno centralizó el poder, creó Carabineros de Chile y promovió grandes obras financiadas con deuda.','Regresó por elección en 1952; creó el Banco del Estado y enfrentó inflación y protestas sociales.']},
{n:'Juan Esteban Montero',o:'Presidente',y:'1931–1932',c:'XX',p:'Radical',r:'No',s:'Santiago',a:'Española',w:'Golpe de 1932',d:'No',x:['Intentó restaurar la legalidad constitucional y ordenar las finanzas durante la Gran Depresión.','La austeridad y el desempleo debilitaron su gobierno, derrocado en junio de 1932 por un movimiento militar.']},
{n:'Pedro Aguirre Cerda',o:'Presidente',y:'1938–1941',c:'XX',p:'Radical',r:'No',s:'Pocuro',a:'Española',w:'Segunda Guerra Mundial — neutralidad',d:'Sí',x:['Bajo el lema “Gobernar es educar”, expandió escuelas y formación técnica tras el terremoto de Chillán.','Creó CORFO en 1939, base de la industrialización estatal chilena; murió en ejercicio.']},
{n:'Juan Antonio Ríos',o:'Presidente',y:'1942–1946',c:'XX',p:'Radical',r:'No',s:'Cañete',a:'Española',w:'Segunda Guerra Mundial',d:'Sí',x:['Rompió relaciones con las potencias del Eje en 1943 y declaró la guerra a Japón en 1945.','Continuó la industrialización mediante CORFO y promovió empresas estratégicas; murió antes de terminar su mandato.']},
{n:'Gabriel González Videla',o:'Presidente',y:'1946–1952',c:'XX',p:'Radical',r:'No',s:'La Serena',a:'Española',w:'Guerra Fría; conflicto político interno',d:'No',x:['Impulsó el Plan Serena, la siderúrgica de Huachipato y la infraestructura productiva del Estado.','Promulgó el sufragio femenino pleno en 1949, pero también la Ley de Defensa Permanente de la Democracia que proscribió al Partido Comunista.']},
{n:'Jorge Alessandri',o:'Presidente',y:'1958–1964',c:'XX',p:'Independiente',r:'No',s:'Santiago',a:'Italiana',w:'Guerra Fría; reconstrucción del terremoto de 1960',d:'No',x:['Aplicó una administración tecnocrática y un programa de estabilización económica.','Dirigió la reconstrucción tras el terremoto de Valdivia de 1960 e inició una reforma agraria limitada.']},
{n:'Eduardo Frei Montalva',o:'Presidente',y:'1964–1970',c:'XX',p:'Demócrata Cristiano',r:'No',s:'Santiago',a:'Suiza y austriaca',w:'Guerra Fría; tensiones sociales internas',d:'No',x:['Impulsó la “Revolución en Libertad”, la reforma agraria, la sindicalización campesina y la promoción popular.','Avanzó en la chilenización del cobre y amplió vivienda, educación e infraestructura.']},
{n:'Salvador Allende',o:'Presidente',y:'1970–1973',c:'XX',p:'Socialista',r:'No',s:'Valparaíso',a:'Española y belga',w:'Crisis política y golpe de Estado de 1973',d:'Sí',x:['Encabezó la vía chilena al socialismo y logró la nacionalización unánime del cobre en 1971.','Su programa de estatizaciones y reformas se desenvolvió entre polarización, desabastecimiento y conflicto institucional; murió durante el golpe del 11 de septiembre de 1973.']},
{n:'Augusto Pinochet',o:'Jefe de Estado / Presidente',y:'1973–1990',c:'XX',p:'Militar / Independiente',r:'No',s:'Valparaíso',a:'Española y francesa',w:'Dictadura militar; conflicto del Beagle',d:'No',x:['Encabezó una dictadura caracterizada por violaciones sistemáticas de los derechos humanos, represión y exilio.','Impuso profundas reformas económicas y la Constitución de 1980; dejó la presidencia tras perder el plebiscito de 1988.']},
{n:'Patricio Aylwin',o:'Presidente',y:'1990–1994',c:'XX',p:'Demócrata Cristiano',r:'No',s:'Santiago',a:'Española y galesa',w:'Transición democrática y tensiones cívico-militares',d:'No',x:['Condujo el retorno a la democracia y creó la Comisión Rettig para documentar violaciones de derechos humanos.','Combinó crecimiento económico con políticas sociales y reducción significativa de la pobreza.']},
{n:'Eduardo Frei Ruiz-Tagle',o:'Presidente',y:'1994–2000',c:'XX',p:'Demócrata Cristiano',r:'No',s:'Santiago',a:'Suiza, austriaca y española',w:'Crisis asiática; tensiones por la detención de Pinochet',d:'No',x:['Amplió carreteras, aeropuertos y obras públicas mediante concesiones e incorporó a Chile al Mercosur como asociado.','Impulsó la reforma procesal penal y enfrentó la recesión derivada de la crisis asiática.']},
{n:'Ricardo Lagos',o:'Presidente',y:'2000–2006',c:'XXI',p:'PPD / Socialista',r:'No',s:'Santiago',a:'Española',w:'Pos-11 de septiembre; negativa a apoyar la guerra de Irak',d:'No',x:['Implementó el plan AUGE de garantías de salud, el seguro de desempleo y nuevas concesiones de infraestructura.','Firmó tratados de libre comercio con Estados Unidos, la Unión Europea y China, y promulgó las reformas constitucionales de 2005.']},
{n:'Michelle Bachelet',o:'Presidenta',y:'2006–2010 · 2014–2018',c:'XXI',p:'Socialista',r:'No consecutiva',s:'Santiago',a:'Francesa, suiza y española',w:'Crisis financiera global; terremoto de 2010',d:'No',x:['Fue la primera mujer en presidir Chile; amplió la protección social y creó Chile Crece Contigo y una reforma previsional.','En su segundo mandato impulsó gratuidad educativa, reforma tributaria, unión civil y la despenalización del aborto en tres causales.']},
{n:'Sebastián Piñera',o:'Presidente',y:'2010–2014 · 2018–2022',c:'XXI',p:'Renovación Nacional',r:'No consecutiva',s:'Santiago',a:'Española',w:'Rescate minero de 2010; estallido social de 2019; pandemia',d:'No',x:['Su primer gobierno gestionó la reconstrucción del terremoto de 2010 y el rescate de los 33 mineros de Atacama.','En el segundo enfrentó el estallido social, abrió el proceso constituyente mediante un acuerdo político y administró la pandemia de COVID-19.']},
{n:'Gabriel Boric',o:'Presidente',y:'2022–2026',c:'XXI',p:'Convergencia Social / Frente Amplio',r:'No',s:'Punta Arenas',a:'Croata y española',w:'Crisis migratoria; seguridad interna; guerra en Ucrania',d:'No',x:['Fue el presidente más joven de la historia chilena y condujo dos procesos constitucionales que no obtuvieron aprobación plebiscitaria.','Promulgó la jornada laboral de 40 horas, elevó el salario mínimo y logró una reforma previsional de alcance estructural en 2025.']},
{n:'José Antonio Kast',o:'Presidente',y:'2026–actualidad',c:'XXI',p:'Republicano',r:'No',s:'Santiago',a:'Alemana',w:'Seguridad fronteriza y crimen organizado',d:'No',x:['Ganó la elección de 2025 y asumió el 11 de marzo de 2026, tras dos candidaturas presidenciales previas.','Su administración se encuentra en curso; sus prioridades iniciales se concentran en seguridad, control migratorio y reactivación económica.']}
];
